secant &lt;- function(f, x0, x1, tol = 1e-12, maxit = 50) {
  f0 &lt;- f(x0); f1 &lt;- f(x1)
  for (k in 1:maxit) {
    step &lt;- f1 * (x1 - x0) / (f1 - f0)
    x0 &lt;- x1; f0 &lt;- f1                           # shift the pair
    x1 &lt;- x1 - step; f1 &lt;- f(x1)
    if (abs(step) &lt;= tol * abs(x1)) return(list(root = x1, iter = k))
  }
  warning("no convergence after ", maxit, " steps")
  list(root = x1, iter = maxit)
}
