fd_jacobian &lt;- function(F, x, h = sqrt(.Machine$double.eps)) {
  Fx &lt;- F(x)
  Jm &lt;- matrix(0, length(Fx), length(x))
  for (j in seq_along(x)) {
    hj &lt;- h * max(abs(x[j]), 1)          # step relative to the size of x[j]
    xh &lt;- x; xh[j] &lt;- x[j] + hj          # nudge only x[j]
    Jm[, j] &lt;- (F(xh) - Fx) / hj         # column j
  }
  Jm
}
