# (c) damped Newton: halve the step until x stays &gt;= 0 and ||F|| does not grow
newton_damped &lt;- function(F, J, x, tol = 1e-12, maxit = 50) {
  for (k in 1:maxit) {
    delta &lt;- solve(J(x), -F(x))
    t &lt;- 1
    while (any(x + t * delta &lt; 0) ||
           sqrt(sum(F(x + t * delta)^2)) &gt; sqrt(sum(F(x)^2))) {
      t &lt;- t / 2
      if (t &lt; 1e-10) stop("damping failed")
    }
    x &lt;- x + t * delta
    cat(k, t, format(x, digits = 10), "\n")
    if (sqrt(sum((t * delta)^2)) &lt; tol) return(x)
  }
  x
}
