def pinv(A, rtol=None):
    if rtol is None:
        rtol = max(A.shape) * np.finfo(float).eps
    U, d, Vt = np.linalg.svd(A, full_matrices=False)
    keep = d &gt; rtol * d[0]                 # drop (numerically) zero sigmas
    return Vt[keep, :].T @ (U[:, keep].T / d[keep][:, None])

