lu_nopivot &lt;- function(A) {
  n &lt;- nrow(A); L &lt;- diag(n); U &lt;- A
  for (k in 1:(n - 1)) {
    for (i in (k + 1):n) {
      L[i, k] &lt;- U[i, k] / U[k, k]                       # multiplier l_ik
      U[i, k:n] &lt;- U[i, k:n] - L[i, k] * U[k, k:n]       # row i minus l_ik * row k
    }
  }
  list(L = L, U = U)
}
forward_sub &lt;- function(L, b) {          # solve L y = b, top to bottom
  n &lt;- length(b); y &lt;- numeric(n)
  for (i in 1:n) {
    j &lt;- seq_len(i - 1)                  # columns 1..i-1
    y[i] &lt;- (b[i] - sum(L[i, j] * y[j])) / L[i, i]
  }
  y
}
back_sub &lt;- function(U, y) {             # solve U x = y, bottom to top
  n &lt;- length(y); x &lt;- numeric(n)
  for (i in n:1) {
    j &lt;- seq_len(n - i) + i              # columns i+1..n
    x[i] &lt;- (y[i] - sum(U[i, j] * x[j])) / U[i, i]
  }
  x
}

