            nbis += 1;
        }
        old_step = xnew - x;
        if old_step.abs() &lt;= tol * xnew.abs() {
            return (xnew, k, nbis);
        }
        x = xnew;
    }
    eprintln!("warning: no convergence");
    (x, maxit, nbis)
}

