import numpy as np
from scipy import sparse
from scipy.sparse.linalg import spsolve, cg as scipy_cg

def jacobi(A, b, tol=1e-10, maxit=20000):
    x = np.zeros(len(b)); dA = A.diagonal()
    for it in range(1, maxit + 1):
        x = x + (b - A @ x) / dA
        if np.linalg.norm(b - A @ x) &lt; tol:
            return x, it
    return x, None                              # not converged

def cg(A, b, tol=1e-10, maxit=20000):
    x = np.zeros(len(b)); r = b.copy(); p = r.copy(); rr = r @ r
    for it in range(1, maxit + 1):
        Ap = A @ p
        alpha = rr / (p @ Ap)
        x = x + alpha * p
        r = r - alpha * Ap
        rr_new = r @ r
        if np.sqrt(rr_new) &lt; tol:
            return x, it
        p = r + (rr_new / rr) * p
        rr = rr_new
    return x, None

