// polynomials in u as coefficient vectors [a0, a1, a2, ...]
fn pmul(a: &[f64], b: &[f64]) -&gt; Vec&lt;f64&gt; {
    let mut out = vec![0.0; a.len() + b.len() - 1];
    for i in 0..a.len() {
        for j in 0..b.len() {
            out[i + j] += a[i] * b[j];
        }
    }
    out
}
fn pder(a: &[f64]) -&gt; Vec&lt;f64&gt; {
    (1..a.len()).map(|i| a[i] * i as f64).collect()
}
fn peval(a: &[f64], x: f64) -&gt; f64 {
