// rust/examples/fourier_fft_c1.rs  —  cargo run --release --example fourier_fft_c1
// C1: the DFT as an n x n matrix (hand-written, O(n^2)) against rustfft.
use rustfft::{num_complex::Complex, FftPlanner};
use std::f64::consts::PI;
use std::time::Instant;

// The DFT matrix F[j][k] = w^(jk), w = exp(-2 pi i / n)
fn dft_matrix(n: usize) -&gt; Vec&lt;Vec&lt;Complex&lt;f64&gt;&gt;&gt; {
    (0..n).map(|j| (0..n).map(|k| {
        Complex::from_polar(1.0, -2.0 * PI * ((j * k) % n) as f64 / n as f64)
    }).collect()).collect()
}

fn matvec(f: &[Vec&lt;Complex&lt;f64&gt;&gt;], x: &[f64]) -&gt; Vec&lt;Complex&lt;f64&gt;&gt; {
    f.iter().map(|row| row.iter().zip(x).map(|(a, &b)| a * b).sum()).collect()
}

fn main() {
    let f4 = dft_matrix(4);
    let x4 = matvec(&f4, &[3.0, 1.0, 1.0, 3.0]);              // check B1
    let s: Vec&lt;String&gt; = x4.iter()
        .map(|z| format!("{}{:+}i", z.re.round() + 0.0, z.im.round() + 0.0)).collect();
    println!("{}", s.join(" "));
    for j in 0..4 {                                            // conj(F)^T F = 4 I
        let row: Vec&lt;f64&gt; = (0..4).map(|k| {
            let s: Complex&lt;f64&gt; = (0..4).map(|m| f4[m][j].conj() * f4[m][k]).sum();
            s.re.round() + 0.0
        }).collect();
        println!("{:?}", row);
    }
    let mut planner = FftPlanner::&lt;f64&gt;::new();
    for n in [256, 512, 1024, 2048] {
        let x: Vec&lt;f64&gt; = (0..n).map(|j| (0.1 * (j * j) as f64).sin()).collect();
        let t0 = Instant::now();
        let x1 = matvec(&dft_matrix(n), &x);
        let t_mat = t0.elapsed().as_secs_f64();
        let fft = planner.plan_fft_forward(n);
        let t0 = Instant::now();
        let mut x2 = Vec::new();
        for _ in 0..100 {
            x2 = x.iter().map(|&v| Complex::new(v, 0.0)).collect();
            fft.process(&mut x2);
        }
        let t_fft = t0.elapsed().as_secs_f64() / 100.0;
        let diff = x1.iter().zip(&x2).map(|(a, b)| (a - b).norm()).fold(0.0, f64::max);
        println!("n = {:4}  max diff {:.1e}  matrix {:.3} s  fft {:.6} s", n, diff, t_mat, t_fft);
    }
}

// Output:
// 8+0i 2+2i 0+0i 2-2i
// [4.0, 0.0, 0.0, 0.0]
// [0.0, 4.0, 0.0, 0.0]
// [0.0, 0.0, 4.0, 0.0]
// [0.0, 0.0, 0.0, 4.0]
// n =  256  max diff 1.8e-14  matrix 0.003 s  fft 0.000001 s
// n =  512  max diff 5.6e-14  matrix 0.013 s  fft 0.000002 s
// n = 1024  max diff 1.0e-13  matrix 0.052 s  fft 0.000005 s
// n = 2048  max diff 1.9e-13  matrix 0.208 s  fft 0.000010 s




Matches B1, and \(\bar F^TF = 4I\). (b) The matrix time grows by about 4 when \(n\) doubles (\(n^2\)); the FFT by about 2 (\(n\log n\)). At \(n = 2048\) the FFT is several thousand times faster. Your timings will differ; the growth factors will not. (c) The matrix is less accurate in R and Python: computing \(e^{-2\pi i jk/n}\) with \(jk\) up to \(4\times10^6\) evaluates sine and cosine at arguments up to \(2\pi \cdot 2047\), and the rounding error of a large argument (about \(\varepsilon \cdot 13\,000\)) carries into every entry. The Rust version reduces \(jk \bmod n\) first, which removes most of it. The FFT uses only \(w^k\) with \(k &lt; n\) and does far fewer operations, so it also makes fewer rounding errors.










