shift_of &lt;- function(A, type) {
  n &lt;- nrow(A)
  if (type == "none") return(0)
  if (type == "rayleigh") return(A[n, n])
  a &lt;- A[n - 1, n - 1]; b &lt;- A[n, n - 1]; c &lt;- A[n, n]   # Wilkinson
  d &lt;- (a - c) / 2
  s &lt;- if (d &gt;= 0) 1 else -1
