import numpy as np

def shift_of(A, kind):
    if kind == "none":
        return 0.0
    if kind == "rayleigh":
        return A[-1, -1]
    a, b, c = A[-2, -2], A[-1, -2], A[-1, -1]        # Wilkinson
    d = (a - c) / 2
    s = 1.0 if d &gt;= 0 else -1.0
    return c - s * b**2 / (abs(d) + np.sqrt(d**2 + b**2))

def qr_eig(A, kind="rayleigh", tol=1e-12, maxit=500):
    lam, steps = [], 0
    while A.shape[0] &gt; 1 and steps &lt; maxit:
        n = A.shape[0]
        mu = shift_of(A, kind)
        Q, R = np.linalg.qr(A - mu * np.eye(n))
        A = R @ Q + mu * np.eye(n)
        steps += 1
        if abs(A[-1, -2]) &lt; tol:                     # deflate
            lam.insert(0, A[-1, -1])
            A = A[:-1, :-1]
    return list(np.diag(A)) + lam, steps

