  u &lt;- x[1]; v &lt;- x[2]
  list(c(alpha / (1 + v^n) - u,          # du/dt
         alpha / (1 + u^n) - v))         # dv/dt
}
J &lt;- function(x) {                       # Jacobian, as in Newton for systems
  u &lt;- x[1]; v &lt;- x[2]
  matrix(c(-1, -alpha * n * v^(n - 1) / (1 + v^n)^2,
           -alpha * n * u^(n - 1) / (1 + u^n)^2, -1),
         nrow = 2, byrow = TRUE)
}
out &lt;- ode(y = c(u = 0.5, v = 0.3), times = c(0, 1, 5, 20), func = toggle,
           parms = NULL, rtol = 1e-10, atol = 1e-12)
for (i in 1:nrow(out)) cat(sprintf("t = %4.1f   u = %.6f   v = %.6f\n", out[i, 1], out[i, 2], out[i, 3]))
x_on &lt;- c((3 + sqrt(5)) / 2, (3 - sqrt(5)) / 2)   # "U on", exact
eigen(J(x_on))$values

# Output:
# t =  0.0   u = 0.500000   v = 0.300000
# t =  1.0   u = 1.323446   v = 0.968978
# t =  5.0   u = 1.628535   v = 0.872293
# t = 20.0   u = 2.587075   v = 0.393849
# [1] -1.6666667 -0.3333333


import numpy as np
from scipy.integrate import solve_ivp

alpha, n = 3.0, 2.0

def toggle(t, x):                        # solve_ivp wants fun(t, x) -&gt; derivatives
    u, v = x
    return [alpha / (1 + v**n) - u,      # du/dt
            alpha / (1 + u**n) - v]      # dv/dt

def J(x):                                # Jacobian, as in Newton for systems
    u, v = x
    return np.array([[-1, -alpha * n * v**(n - 1) / (1 + v**n)**2],
                     [-alpha * n * u**(n - 1) / (1 + u**n)**2, -1]])

sol = solve_ivp(toggle, (0, 20), [0.5, 0.3], t_eval=[0, 1, 5, 20],
                rtol=1e-10, atol=1e-12)
for t, u, v in zip(sol.t, *sol.y):
    print(f"t = {t:4.1f}   u = {u:.6f}   v = {v:.6f}")
x_on = np.array([(3 + np.sqrt(5)) / 2, (3 - np.sqrt(5)) / 2])   # "U on", exact
print(np.linalg.eigvals(J(x_on)))

