def classify(A, tol=1e-8):
    lam = np.linalg.eigvals(A)
    re, im = lam.real, lam.imag
    if np.any(np.abs(re) &lt; tol):
        return "undecided (Re = 0)"
    if np.any(re &gt; 0) and np.any(re &lt; 0):
        return "saddle"
    return ("stable" if np.all(re &lt; 0) else "unstable") + \
           (" spiral" if np.any(np.abs(im) &gt; tol) else " node")

def fmt(lam):                            # sort by real part, then imaginary part
    lam = sorted(lam, key=lambda z: (-z.real, -z.imag))
    return " ".join(f"{z.real:8.4f}{z.imag:+.4f}i" for z in lam)

