    Fx = F(x); Jm = np.zeros((len(Fx), len(x)))
    for j in range(len(x)):
        hj = h * max(abs(x[j]), 1); xh = x.copy(); xh[j] += hj
        Jm[:, j] = (F(xh) - Fx) / hj
    return Jm

