import numpy as np
import matplotlib.pyplot as plt

def euler_step(f, t, y, h):
    return y + h * f(t, y)

def midpoint_step(f, t, y, h):
    k1 = f(t, y)
    k2 = f(t + h / 2, y + h / 2 * k1)
    return y + h * k2

def heun_step(f, t, y, h):
    k1 = f(t, y)
    k2 = f(t + h, y + h * k1)
    return y + h / 2 * (k1 + k2)

def rk4_step(f, t, y, h):
    k1 = f(t, y)
    k2 = f(t + h / 2, y + h / 2 * k1)
    k3 = f(t + h / 2, y + h / 2 * k2)
    k4 = f(t + h, y + h * k3)
    return y + h / 6 * (k1 + 2 * k2 + 2 * k3 + k4)

def rk_solve(step, f, t0, y0, h, n):
    t = t0 + h * np.arange(n + 1)
    Y = np.zeros((n + 1, np.size(y0))); Y[0] = y0
    for i in range(n):
        Y[i + 1] = step(f, t[i], Y[i], h)
    return t, Y

