import numpy as np

def adapt_heun(f, t, y, tend, h, rtol=1e-6, atol=1e-9):
    y = np.atleast_1d(np.asarray(y, dtype=float))
    ts, hs, Y, nrej = [t], [], [y], 0
    while t &lt; tend:
        h = min(h, tend - t)
        k1 = f(t, y); k2 = f(t + h, y + h * k1)
        ylo = y + h * k1                         # Euler, order 1
        yhi = y + h / 2 * (k1 + k2)              # Heun, order 2
        sc = atol + rtol * np.maximum(np.abs(y), np.abs(yhi))
        err = np.sqrt(np.mean(((yhi - ylo) / sc) ** 2))
        if err &lt;= 1:                             # accept and record
            t, y = t + h, yhi
            ts.append(t); hs.append(h); Y.append(y)
        else:                                    # reject: retry with smaller h
            nrej += 1
        h = h * min(5, max(0.2, 0.9 * err ** -0.5))
    return np.array(ts), np.array(hs), np.array(Y), nrej
