import numpy as np

def model(t):
    return 500 / 50 * 1.5 / 1.3 * (np.exp(-0.2 * t) - np.exp(-1.5 * t))
exact = 32.6243601574044                   # AUC 0-6 h
def left(f, a, b, n):
    h = (b - a) / n
    return h * np.sum(f(a + np.arange(n) * h))
def mid(f, a, b, n):
    h = (b - a) / n
    return h * np.sum(f(a + (np.arange(1, n + 1) - 0.5) * h))
def trap(f, a, b, n):
    x = np.linspace(a, b, n + 1); y = f(x); h = (b - a) / n
    return h * (np.sum(y) - (y[0] + y[-1]) / 2)
def simpson(f, a, b, n):
    x = np.linspace(a, b, n + 1); h = (b - a) / n
    w = np.r_[1, np.tile([4, 2], n // 2 - 1), 4, 1]
    return h / 3 * np.sum(w * f(x))

rules = [left, mid, trap, simpson]
n = 2 ** np.arange(1, 11)
E = np.array([[abs(r(model, 0, 6, k) - exact) for r in rules] for k in n])
for k, row in zip(n, E):
    if k in (4, 8, 16, 1024):
