    let (x, y): (Vec&lt;f64&gt;, Vec&lt;f64&gt;) = (7..10).map(|i| (t[i], c[i].ln())).unzip();
    let (mx, my) = (x.iter().sum::&lt;f64&gt;() / 3.0, y.iter().sum::&lt;f64&gt;() / 3.0);
    let sxy: f64 = x.iter().zip(&y).map(|(a, b)| (a - mx) * (b - my)).sum();
    let sxx: f64 = x.iter().map(|a| (a - mx).powi(2)).sum();
    let lz = -sxy / sxx;
