import numpy as np
from scipy.stats import poisson

rng = np.random.default_rng(1)

def ssa(x, S, propensity, times):         # S: species x reactions
    x = np.array(x, dtype=float)
    out = np.zeros((len(times), len(x)))
    t, i = 0.0, 0
    while True:
        a = np.cumsum(propensity(x)); a0 = a[-1]
        t += -np.log(1 - rng.random()) / a0 if a0 &gt; 0 else np.inf
        while i &lt; len(times) and times[i] &lt; t:
            out[i] = x; i += 1
        if i == len(times):
            return out
        j = np.searchsorted(a, rng.random() * a0, side="right")  # reaction j w.p. a_j / a0
        x += S[:, j]

def fano(v):
    return v.var(ddof=1) / v.mean()

