// C3: averaging over events instead of over time biases the mean.
use rand::{rngs::StdRng, RngExt, SeedableRng};

fn main() {
    let (k, delta) = (10.0, 1.0);
    let mut rng = StdRng::seed_from_u64(1);
    let (mut t, mut m) = (0.0f64, 0i64);
    let (mut n_ev, mut sum_ev, mut area) = (0u64, 0i64, 0.0f64); // after a 10 h burn-in
    while t &lt; 5000.0 {
        let (a1, a2) = (k, delta * m as f64);
        let a0 = a1 + a2;
        let tau = -(1.0 - rng.random::&lt;f64&gt;()).ln() / a0;
        if t &gt; 10.0 { area += m as f64 * tau; } // m holds for a time tau
        t += tau;
        m += if rng.random::&lt;f64&gt;() * a0 &lt; a1 { 1 } else { -1 };
        if t &gt; 10.0 { n_ev += 1; sum_ev += m; } // one record per event
    }
    println!("per event {:.4}   time-weighted {:.4}   ({} events)",
             sum_ev as f64 / n_ev as f64, area / (t - 10.0), n_ev);
}

// Output:
// per event 10.3702   time-weighted 9.8655   (98946 events)



The time-weighted mean (9.96, 10.03, 9.87) is right; the per-event mean (10.46, 10.52, 10.37) is about 0.5 too high in all three languages. Events happen at rate \(a_0 = 10 + m\), so a state \(n\) is the starting point of a fraction \(\propto P_n (10 + n)\) of the events, giving a mean pre-event state of \(\frac{\mathrm E[m(10 + m)]}{\mathrm E[10 + m]} = \frac{100 + 110}{20} = 10.5\) (and the same for the state after the event). Recording a value per event weights each state by how often it changes, not by how long it lasts.
