// rust/examples/gillespie_c4.rs  —  cargo run --release --example gillespie_c4
// C4: tau-leaping for mRNA birth-death; variance and negative counts versus tau.
use rand::{rngs::StdRng, SeedableRng};
use rand_distr::{Distribution, Poisson};

fn rpois(lambda: f64, rng: &mut StdRng) -&gt; i64 {
    if lambda &lt;= 0.0 { 0 } else { Poisson::new(lambda).unwrap().sample(rng) as i64 }
}

fn tau_leap(tau: f64, rng: &mut StdRng) -&gt; (i64, bool) {
    let (t_end, k, delta) = (10.0, 10.0, 1.0);
    let (mut m, mut went_negative) = (0i64, false);
    for _ in 0..(t_end / tau as f64).round() as usize {
        m += rpois(k * tau, rng) - rpois(delta * m as f64 * tau, rng); // many reactions per leap
        if m &lt; 0 { went_negative = true; m = 0; } // impossible: clip
    }
    (m, went_negative)
}

fn main() {
    let mut rng = StdRng::seed_from_u64(1);
    for tau in [0.01, 0.1, 0.5, 1.0, 1.5] {
        let r: Vec&lt;(i64, bool)&gt; = (0..2000).map(|_| tau_leap(tau, &mut rng)).collect();
        let n = r.len() as f64;
        let mean = r.iter().map(|x| x.0 as f64).sum::&lt;f64&gt;() / n;
        let var = r.iter().map(|x| (x.0 as f64 - mean).powi(2)).sum::&lt;f64&gt;() / (n - 1.0);
        let neg = r.iter().filter(|x| x.1).count() as f64 / n;
        println!("tau {:4.2}  mean {:6.3}  var {:6.3}  theory var {:6.3}  negative {:.4}",
                 tau, mean, var, 20.0 / (2.0 - tau), neg);
    }
}

// Output:
// tau 0.01  mean 10.056  var  9.901  theory var 10.050  negative 0.0005
// tau 0.10  mean 10.011  var 10.932  theory var 10.526  negative 0.0030
// tau 0.50  mean 10.085  var 13.937  theory var 13.333  negative 0.0075
// tau 1.00  mean  9.976  var 19.030  theory var 20.000  negative 0.0965
// tau 1.50  mean 10.019  var 32.193  theory var 40.000  negative 0.3295



The mean stays near 10 for all \(\tau\) (for linear propensities tau-leaping gets the mean right), but the variance follows the tau-leap formula \(20/(2 - \tau)\) instead of the exact 10: twice too large at \(\tau = 1\). At \(\tau = 1.5\) the clipping at zero holds the variance below the formula, and about a third of the runs went negative. Small \(\tau\) (0.01) is accurate but costs 1000 steps for 10 h, five times more than the about 200 SSA steps: tau-leaping pays only when \(a_0 \tau \gg 1\), i.e. for abundant species.
