import numpy as np

rng = np.random.default_rng(1)

def em(h, k, t_end=10, delta=1):          # chemical Langevin equation
    m = 0.0
    for n in range(round(t_end / h)):
        m += (k - delta * m) * h + np.sqrt((k + delta * m) * h) * rng.standard_normal()
    return m

m = np.array([em(0.01, k=10) for _ in range(2000)])
print("mean", m.mean(), " var", m.var(ddof=1), " fano", m.var(ddof=1) / m.mean())
