import numpy as np

rng = np.random.default_rng(1)

def sir_fate(I0, N=10000, beta=0.3, gamma=0.1):
    S, I = N - I0, I0
    while 0 &lt; I &lt; 100:                       # stop: extinct, or 100 infected
        a1, a2 = beta * S * I / N, gamma * I # infection, recovery
        if rng.random() * (a1 + a2) &lt; a1:
            S, I = S - 1, I + 1
        else:
            I -= 1
    return I == 0                            # True if the outbreak died out

for I0 in [1, 2, 3]:
    ext = np.array([sir_fate(I0) for _ in range(10000)])
    print(f"I0 = {I0}  extinct {ext.mean():.4f}  se {ext.std(ddof=1) / 100:.4f}"
          f"  branching (1/3)^I0 = {(1 / 3)**I0:.4f}")
