        if delta.norm() &lt; 1e-8 * (1.0 + q.norm()) { break; }
    }
    // Levenberg-Marquardt in log parameters from the same start
    let q0 = DVector::from_vec(vec![3.0f64.ln(), 0.05f64.ln(), 50.0f64.ln()]);
    let (q, r, k) = lev_mar(&f_log, q0);
    let p = q.map(f64::exp);
    println!("{:.7} {:.7} {:.7}  RSS {:.7}  iter {}", p[0], p[1], p[2], r, k);
}

