from scipy.integrate import solve_ivp
from scipy import sparse
D, L = 1000.0, 500.0
def mol(N, method, rtol=1e-6, atol=1e-6):
    dx = L / N; x = np.linspace(0, L, N + 1)
    def rhs(t, c):                                  # interior points only
        return D * np.diff(np.r_[1.0, c, 0.0], 2) / dx**2   # source 1, sink 0
    kw = {}
    if method == "BDF":                             # tridiagonal Jacobian pattern
        kw["jac_sparsity"] = sparse.diags([1, 1, 1], [-1, 0, 1], shape=(N - 1, N - 1))
    if method == "LSODA":                           # LSODA takes the band widths
        kw["lband"] = kw["uband"] = 1
    s = solve_ivp(rhs, (0, 60), np.zeros(N - 1), method=method, rtol=rtol, atol=atol, **kw)
    err = np.max(np.abs(s.y[:, -1] - exact(x[1:N], 60, L, D)))
    return f"steps {s.t.size - 1:6d}  f-evals {s.nfev:6d}  error {err:.3e}"

