                let small = step.norm() &lt; 1e-12 * (1.0 + DVector::from_vec(p.clone()).norm());
                p = pn;
                mu = (mu / 10.0).max(1e-12);
                if small { return p; }
                break;
            }
            mu *= 10.0;
            if mu &gt; 1e12 { return p; }
        }
    }
    p
}

