// rust/examples/identifiability_q11.rs  —  cargo run --example identifiability_q11
// Quiz Q11: standard errors via QR, and the correlation matrix.
#![allow(dead_code)]
use nalgebra::{DMatrix, DVector};

// One-compartment model with oral absorption, dose D = 100 mg (mg/L)
const D: f64 = 100.0; // oral dose, mg
fn bateman(t: f64, ka: f64, ke: f64, v: f64) -&gt; f64 {
    D * ka / (v * (ka - ke)) * ((-ke * t).exp() - (-ka * t).exp())
}
const TT: [f64; 12] = [0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 4.0, 6.0, 8.0, 10.0, 12.0];
const Y: [f64; 12] = [1.02, 1.88, 2.34, 2.98, 3.27, 3.26, 3.17, 2.77, 1.92, 1.23, 1.00, 0.61];

// Central-difference Jacobian of f at p (like numDeriv::jacobian, less refined)
fn jacobian(f: &dyn Fn(&[f64]) -&gt; Vec&lt;f64&gt;, p: &[f64]) -&gt; DMatrix&lt;f64&gt; {
    let n = f(p).len();
    let mut j = DMatrix::zeros(n, p.len());
    for k in 0..p.len() {
        let h = 1e-5 * p[k].abs().max(1.0);
        let (mut pp, mut pm) = (p.to_vec(), p.to_vec());
        pp[k] += h;
        pm[k] -= h;
        let (fp, fm) = (f(&pp), f(&pm));
        for i in 0..n { j[(i, k)] = (fp[i] - fm[i]) / (2.0 * h); }
    }
    j
}

// Levenberg-Marquardt for min sum r(p)^2, hand-written (R: nls / nls.lm, Python: least_squares)
fn levmar(r: &dyn Fn(&[f64]) -&gt; Vec&lt;f64&gt;, p0: &[f64]) -&gt; Vec&lt;f64&gt; {
    let ss = |p: &[f64]| -&gt; f64 { let v = r(p); if v.iter().all(|x| x.is_finite()) { v.iter().map(|x| x * x).sum() } else { f64::INFINITY } };
    let (mut p, mut mu) = (p0.to_vec(), 1e-3);
    for _ in 0..500 {
        let j = jacobian(r, &p);                     // Jacobian of the residuals
        let rv = DVector::from_vec(r(&p));
        let jtj = j.transpose() * &j;
        let g = j.transpose() * &rv;
        loop {
            let a = &jtj + DMatrix::from_diagonal(&jtj.diagonal()) * mu;
            let step = a.lu().solve(&(-&g)).unwrap();
            let pn: Vec&lt;f64&gt; = p.iter().zip(step.iter()).map(|(a, b)| a + b).collect();
            if ss(&pn) &lt;= ss(&p) {
                let small = step.norm() &lt; 1e-12 * (1.0 + DVector::from_vec(p.clone()).norm());
                p = pn;
                mu = (mu / 10.0).max(1e-12);
                if small { return p; }
                break;
            }
            mu *= 10.0;
            if mu &gt; 1e12 { return p; }
        }
    }
    p
}

// Residuals y - C(t) for the one-compartment model at the sample times ts
fn resid(ts: &[f64], ys: &[f64]) -&gt; impl Fn(&[f64]) -&gt; Vec&lt;f64&gt; {
    let (ts, ys) = (ts.to_vec(), ys.to_vec());
    move |p: &[f64]| ts.iter().zip(&ys).map(|(ti, yi)| yi - bateman(*ti, p[0], p[1], p[2])).collect()
}
fn sse(r: &dyn Fn(&[f64]) -&gt; Vec&lt;f64&gt;, p: &[f64]) -&gt; f64 { r(p).iter().map(|x| x * x).sum() }

fn main() {
    let r = resid(&TT, &Y);
    let th = levmar(&r, &[0.5, 0.1, 10.0]);
    let j = jacobian(&r, &th);
    let s2 = sse(&r, &th) / (TT.len() - th.len()) as f64;
    let rinv = j.qr().r().try_inverse().unwrap();
    let cv = &rinv * rinv.transpose() * s2;
    let se: Vec&lt;f64&gt; = (0..3).map(|i| cv[(i, i)].sqrt()).collect();
    println!("{:.4} {:.4} {:.4}", se[0], se[1], se[2]);
    let cor = DMatrix::from_fn(3, 3, |i, k| cv[(i, k)] / (se[i] * se[k]));
    for i in 0..3 {
        println!("{:6.2} {:6.2} {:6.2}", cor[(i, 0)], cor[(i, 1)], cor[(i, 2)]);
    }
}

// Output:
// 0.0624 0.0104 0.7165
//   1.00  -0.82   0.90
//  -0.82   1.00  -0.91
//   0.90  -0.91   1.00



These are the numbers of vcov(fit) and cov2cor (exercise C1). The R and Python versions continue from the setup block of the exercise; the Rust file is complete.

Background
Facts used below:

Steady state. With \(\partial c/\partial t = 0\), diffusion with uptake \(r(c)\) becomes the boundary value problem \(D\,\nabla^2 c = r(c)\), with \(\nabla^2 c = \partial^2 c/\partial x^2 + \partial^2 c/\partial y^2\). Constant \(r\): Poisson equation; \(r = 0\): Laplace equation. Only boundary conditions, no initial condition.
1D grid. Nodes \(x_i = i\,h\), \(i = 0, \dots, N\), as in The diffusion (heat) equation by finite differences (\(h\) is its \(\Delta x\)). Two differences from that unit: we write minus the second difference (diagonal \(+2\)), so the matrix is symmetric positive definite and Cholesky and CG apply; and concentrations are in µM (or mM), not scaled to 0..1, because thresholds and \(K_m\) are absolute. Interior equation: \[\frac{D}{h^2}\bigl(-c_{i-1} + 2c_i - c_{i+1}\bigr) + r(c_i) = 0.\] A known boundary value \(c_0\) moves to the right-hand side: \(+\frac{D}{h^2}c_0\) in the first equation.
No flux at a closed end \(x_N\): ghost point \(c_{N+1} = c_{N-1}\), so the last equation is \(\frac{D}{h^2}\bigl(-2c_{N-1} + 2c_N\bigr) + r(c_N) = 0\), and \(c_N\) is an unknown.
Second difference has error \(O(h^2)\), and is exact for parabolas: with constant uptake the grid solution equals the exact one at the grid points.
2D grid with the same \(h\) in \(x\) and \(y\): five-point stencil \(\frac{D}{h^2}\bigl(4c_{i,j} - c_{i-1,j} - c_{i+1,j} - c_{i,j-1} - c_{i,j+1}\bigr) + r(c_{i,j}) = 0\). Numbering with \(x\) running fastest: \(k = i + (j-1)\,n_x\) (1-based), neighbours at \(k \pm 1\) and \(k \pm n_x\).
Kronecker product: \(A \otimes B\) replaces each \(a_{pq}\) by the block \(a_{pq}B\). With \(T_n = \text{tridiag}(-1, 2, -1)\) of size \(n\) and \(x\) running fastest: \[A = \frac{D}{h^2}\bigl(I_{n_y}\otimes T_{n_x} + T_{n_y}\otimes I_{n_x}\bigr).\] With \(y\) running fastest the factors swap: \(T_{n_x}\otimes I_{n_y} + I_{n_x}\otimes T_{n_y}\).
Storage order. R stores matrices column by column, so as.vector(C) of an \(n_x \times n_y\) matrix C[i, j] puts \(x\) fastest. numpy’s C.ravel() and C.reshape(...) are row-major by default (\(y\) fastest); order="F" gives R’s order. In this exercise every language uses \(x\) fastest.
Michaelis–Menten uptake \(r(c) = R_0\,c/(K_m + c)\), \(r'(c) = R_0K_m/(K_m + c)^2\). Newton for \(\mathbf F(\mathbf c) = A\mathbf c + r(\mathbf c) - \mathbf b = \mathbf 0\): solve \(J\boldsymbol\delta = -\mathbf F\) with \(J = A + \operatorname{diag}(r'(c_k))\), then \(\mathbf c \leftarrow \mathbf c + \boldsymbol\delta\).

Numbers. Oxygen: \(D = 2000\) µm²/s (\(2\times10^{-9}\) m²/s), \(c_0 = 200\) µM, chamber \(4000 \times 2000\) µm, \(R_0 = 0.5\) µM/s per \(10^5\) cells/cm² (an order-of-magnitude assumption: 50 amol/s per cell under a 100 µm lid), \(K_m = 1\) µM, hypoxic below 10 µM. Mother machine: trench \(L = 25\) µm, glucose \(D = 600\) µm²/s, uptake by the packed cells \(V_{\max} = 0.6\) mM/s and \(K_m = 5\) µM \(= 0.005\) mM (both order-of-magnitude assumptions, see C2), rich medium 0.2 % glucose \(= 11.1\) mM.
The basic tools in each language: the 2D matrix for a \(3 \times 2\) grid (\(D = h = 1\)), and flattening a grid with \(x\) fastest. R: Matrix::bandSparse, kronecker, Diagonal. Python: scipy.sparse.diags, scipy.sparse.kron, scipy.sparse.identity. Rust: sprs::TriMat triplets with the index written out.

