import numpy as np
from scipy import sparse
from scipy.sparse.linalg import spsolve

def trench_matrix(N, h, D):                 # unknowns c_1 .. c_N; c_N at the wall
    lower = -np.ones(N - 1); lower[-1] = -2 # ghost point c_{N+1} = c_{N-1}
    A = sparse.diags([lower, 2 * np.ones(N), -np.ones(N - 1)], [-1, 0, 1], format="csc")
    return D / h**2 * A

