import numpy as np
from scipy import sparse
from scipy.sparse.linalg import spsolve

def trench_matrix(N, h, D):
    lower = -np.ones(N - 1); lower[-1] = -2
    A = sparse.diags([lower, 2 * np.ones(N), -np.ones(N - 1)], [-1, 0, 1], format="csc")
    return D / h**2 * A

def trench_mm(c0, L=25.0, D=600.0, Vmax=0.6, Km=0.005, N=100):
    h = L / N; A = trench_matrix(N, h, D)
    b = np.zeros(N); b[0] = D / h**2 * c0
    c = np.full(N, c0)                                  # start: trench = channel
    for it in range(51):
        F = A @ c + Vmax * c / (Km + c) - b
        if np.linalg.norm(F) &lt; 1e-10 * (1 + np.max(np.abs(b))):
            break
        J = A + sparse.diags(Vmax * Km / (Km + c)**2, format="csc")  # tridiagonal
        c = np.maximum(c + spsolve(J, -F), 0)          # clip: no negative glucose
    if c.min() &lt; 0:
        raise ValueError("negative concentration")
    return c, h * np.arange(1, N + 1), it

for c0 in [11.1, 1, 0.3, 0.1, 0.02]:
    c, x, it = trench_mm(c0)
    starved = np.mean(c &lt; 0.005) * 25                   # µm of trench with c &lt; Km
    print(f"c0 = {c0:5.2f} mM: {it} steps, closed end {c[-1]:.4g} mM, starved {starved:4.1f} um")

