  A &lt;- diag(di, m)
  A[cbind(2:m, 1:(m-1))] &lt;- lo; A[cbind(1:(m-1), 2:m)] &lt;- up
  b &lt;- numeric(m); b[m] &lt;- -up
  c(0, solve(A, b), 1)
}
wiggly &lt;- function(c) any(diff(c) &lt; 0)           # exact profile only increases
Ns &lt;- c(10, 20, 25, 40, 50, 100, 200, 400, 800)
ec &lt;- eu &lt;- numeric(length(Ns))
for (j in seq_along(Ns)) {
  N &lt;- Ns[j]; x &lt;- seq(0, L, length.out = N + 1)
  cc &lt;- steady(N, "central"); cu &lt;- steady(N, "upwind")
  ec[j] &lt;- max(abs(cc - exact(x))); eu[j] &lt;- max(abs(cu - exact(x)))
  cat(sprintf("%4d %6.3f %5.2f %9.2e %-5s %9.2e %-5s\n", N, L / N, u * L / N / D,
