}
k &lt;- length(Ns)                                  # observed order from the last halving
cat(sprintf("order: central %.2f, upwind %.2f\n",
            log2(ec[k - 1] / ec[k]), log2(eu[k - 1] / eu[k])))
for (N in c(10, 50, 200)) {                      # upwind = central with D + u dx / 2
  dx &lt;- L / N
  cat(sprintf("N = %3d: %.1e\n", N,
              max(abs(steady(N, "upwind") - steady(N, "central", D = D + u * dx / 2)))))
}

