import numpy as np
from scipy.special import erfc

u, D = 200.0, 100.0                                # um/s, um^2/s

def pulse(dx, C, tend=16.0):                       # explicit upwind, 1 s inlet pulse
    x = np.arange(0, 3000 + dx / 2, dx); n = len(x)
    dt = C * dx / u; r = D * dt / dx**2
    c = np.zeros(n); obs = np.zeros(round(tend / dt)); big = 0.0
    iobs = np.flatnonzero(x == 2000)[0]
    for k in range(1, len(obs) + 1):
        c[1:-1] = c[1:-1] - C * (c[1:-1] - c[:-2]) + r * (c[:-2] - 2 * c[1:-1] + c[2:])
        c[-1] = c[-2]
        c[0] = 1.0 if k * dt &lt;= 1 else 0.0
        obs[k - 1] = c[iobs]; big = max(big, np.max(np.abs(c)))
    return dict(peak=obs.max(), tpeak=(np.argmax(obs) + 1) * dt, r=r, maxabs=big)

def step(x, t, D):
    tt = np.maximum(t, 1e-12)
    return np.where(t &gt; 0, 0.5 * erfc((x - u * tt) / (2 * np.sqrt(D * tt))), 0.0)

def approx_exact(x, t, D):
    return step(x, t, D) - step(x, t - 1, D)

