import numpy as np
from scipy.linalg import solve_banded

def march(c, u, D, dy, dx, nsteps):                # backward Euler in x
    M = len(c); a = D * dx / (u * dy**2)
    di = 1 + 2 * a; di[[0, -1]] = 1 + a[[0, -1]]   # no-flux walls
    ab = np.zeros((3, M))                          # banded storage: super, main, sub
    ab[0, 1:] = -a[:-1]; ab[1] = di; ab[2, :-1] = -a[1:]
    for _ in range(int(round(nsteps))):
        c = solve_banded((1, 1), ab, c)
    return c

w, ubar, D = 100.0, 1000.0, 1000.0

def plug_exact(y, x, D, K=2001):                   # two streams, plug flow, no-flux walls
    s = 0.5
    for n in range(1, K + 1):
        s = s + 2 / (n * np.pi) * np.sin(n * np.pi / 2) * np.cos(n * np.pi * y / w) * \
            np.exp(-(n * np.pi)**2 * D * x / (ubar * w**2))
    return s

# (a) plug flow against the exact solution at x = 2 mm
M = 200; dy = w / M; y = (np.arange(1, M + 1) - 0.5) * dy; c0 = np.where(y &lt; w / 2, 1.0, 0.0)
ex = plug_exact(y, 2000, D)
for dx in [200, 100, 50, 25, 12.5]:
    cm = march(c0, np.full(M, ubar), D, dy, dx, 2000 / dx)
    print(f"dx = {dx:5.1f}  max error {np.max(np.abs(cm - ex)):.2e}")
# (b) Poiseuille: flux conservation and the explicit step limits
M = 50; dy = w / M; y = (np.arange(1, M + 1) - 0.5) * dy; c0 = np.where(y &lt; w / 2, 1.0, 0.0)
u = 6 * ubar * (y / w) * (1 - y / w)
c2 = march(c0, u, D, dy, 50, 40)
print(f"flux ratio {np.sum(u * c2) / np.sum(u * c0):.12f}")
lim = u * dy**2 / (2 * D)
print(f"explicit dx limit: wall row {lim.min():.4f} um, centre row {lim.max():.4f} um")
# (c) explicit marching, dx = 1 um and 0.1 um, to x = 100 um
def explicit(c, u, D, dy, dx, nsteps):
    a = D * dx / (u * dy**2)
    for _ in range(nsteps):
        g = np.concatenate(([c[0]], c, [c[-1]]))
        c = c + a * (g[:-2] - 2 * c + g[2:])
    return c
print(f"explicit, dx = 1:   max|c| = {np.max(np.abs(explicit(c0, u, D, dy, 1, 100))):.3g}")
print(f"explicit, dx = 0.1: max|c| = {np.max(np.abs(explicit(c0, u, D, dy, 0.1, 1000))):.3g}")

