# import numpy as np; march() as in C3
def stage(c):                                      # n streams -&gt; n + 1 streams
    n = len(c); k = np.arange(n + 1)
    return (k / n) * np.concatenate(([0.0], c)) + ((n - k) / n) * np.concatenate((c, [0.0]))

def tree(inlets, nout):
    c = np.array(inlets, dtype=float)
    while len(c) &lt; nout:
        c = stage(c)
    return c

